#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    tauri::Builder::default()
        .plugin(tauri_plugin_opener::init())
        .plugin(tauri_plugin_notification::init())
        .plugin(tauri_plugin_dialog::init())
        .plugin(tauri_plugin_fs::init())
        .plugin(tauri_plugin_shell::init())
        .plugin(tauri_plugin_process::init())
        .plugin(tauri_plugin_updater::Builder::new().build())
        .plugin(tauri_plugin_clipboard_manager::init())
        .plugin(tauri_plugin_global_shortcut::Builder::new().build())
        .plugin(tauri_plugin_http::init())
        .plugin(tauri_plugin_websocket::init())
        .plugin(tauri_plugin_sql::Builder::default().add_migrations("sqlite:humanity_grid.db", vec![
            tauri_plugin_sql::Migration {
                version: 1,
                description: "create_initial_tables",
                sql: include_str!("../migrations/001_initial.sql"),
                kind: tauri_plugin_sql::MigrationKind::Up,
            }
        ]).build())
        .setup(|app| {
            // Initialize system monitoring
            #[cfg(debug_assertions)]
            {
                let window = app.get_webview_window("main").unwrap();
                window.open_devtools();
            }
            Ok(())
        })
        .invoke_handler(tauri::generate_handler![
            // System info
            get_system_info,
            get_thermal_info,
            get_power_info,
            // BOINC control
            boinc_get_status,
            boinc_start,
            boinc_stop,
            boinc_pause,
            boinc_resume,
            // Settings
            get_settings,
            update_settings,
            // Contributions
            get_contributions,
            get_project_stories,
        ])
        .run(tauri::generate_context!())
        .expect("error while running tauri application");
}

// System info commands
#[tauri::command]
async fn get_system_info() -> Result<SystemInfo, String> {
    let mut sys = sysinfo::System::new_all();
    sys.refresh_all();

    let cpu_usage = sys.global_cpu_usage();
    let total_memory = sys.total_memory();
    let used_memory = sys.used_memory();
    let available_memory = sys.available_memory();

    let cpus = sys.cpus().iter().map(|cpu| CpuInfo {
        name: cpu.name().to_string(),
        usage: cpu.cpu_usage(),
        frequency: cpu.frequency(),
    }).collect();

    let gpus = detect_gpus();

    Ok(SystemInfo {
        cpu_usage,
        total_memory,
        used_memory,
        available_memory,
        cpus,
        gpus,
        os: std::env::consts::OS.to_string(),
        arch: std::env::consts::ARCH.to_string(),
    })
}

#[tauri::command]
async fn get_thermal_info() -> Result<ThermalInfo, String> {
    let mut sys = sysinfo::System::new_all();
    sys.refresh_all();

    let temperatures = sys.components().iter().map(|comp| TemperatureReading {
        label: comp.label().to_string(),
        temperature: comp.temperature(),
        max: comp.max(),
        critical: comp.critical(),
    }).collect();

    Ok(ThermalInfo { temperatures })
}

