export type ProsodyTagAdjustments = {
  speedDelta: number
  pitchDelta: number
  reverbDelta: number
}

export type ProsodyTagParseResult = {
  cleanText: string
  adjustments: ProsodyTagAdjustments
}

const DEFAULT_ADJUSTMENTS: ProsodyTagAdjustments = {
  speedDelta: 0,
  pitchDelta: 0,
  reverbDelta: 0,
}

function clamp(n: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, n))
}

/**
 * SSML-lite deterministic controls:
 * [emph]...[/emph], [strong]...[/strong], [question]...[/question], [pause], [pause:short|medium|long]
 */
export function parseProsodyTags(text: string): ProsodyTagParseResult {
  if (!text) return { cleanText: text, adjustments: { ...DEFAULT_ADJUSTMENTS } }

  let speedDelta = 0
  let pitchDelta = 0
  let reverbDelta = 0

  const emphCount = (text.match(/\[emph\]/gi) || []).length
  const strongCount = (text.match(/\[strong\]/gi) || []).length
  const questionCount = (text.match(/\[question\]/gi) || []).length
  const pauseShort = (text.match(/\[pause:short\]/gi) || []).length
  const pauseMedium = (text.match(/\[pause(?::medium)?\]/gi) || []).length
  const pauseLong = (text.match(/\[pause:long\]/gi) || []).length

  speedDelta += emphCount * 0.02
  pitchDelta += emphCount * 0.6

  speedDelta += strongCount * 0.04
  pitchDelta += strongCount * 1.0

  pitchDelta += questionCount * 0.8

  speedDelta -= pauseShort * 0.01
  speedDelta -= pauseMedium * 0.02
  speedDelta -= pauseLong * 0.03
  reverbDelta += (pauseMedium + pauseLong) * 0.02

  const cleanText = text
    .replace(/\[(\/)?(emph|strong|question)\]/gi, '')
    .replace(/\[pause(?::short|:medium|:long)?\]/gi, ' — ')
    .replace(/\s+/g, ' ')
    .trim()

  return {
    cleanText,
    adjustments: {
      speedDelta: clamp(speedDelta, -0.18, 0.22),
      pitchDelta: clamp(pitchDelta, -6, 8),
      reverbDelta: clamp(reverbDelta, 0, 0.2),
    },
  }
}

/**
 * In-memory TTS response cache for repeat lines (solo-creator workflow).
 * Cache key = hash of text + voice_id + params. Max 200 entries, LRU eviction.
 * March 2026
 */

import { createHash } from 'node:crypto'

const MAX_ENTRIES = 200

interface CacheEntry {
  buffer: ArrayBuffer
  contentType: string
  createdAt: number
}

const cache = new Map<string, CacheEntry>()
const keyOrder: string[] = []

function hash(payload: string): string {
  // Collision-resistant hash so distinct requests do not share audio.
  return createHash('sha256').update(payload).digest('hex')
}

export function buildTtsCacheKey(params: {
  text: string
  voice_id: string
  language: string
  speed: number
  pitch: number
  volume: number
  reverb: number
  echo: number
  noise_reduction: boolean
  special_effect: string
  /** Clone tuning segment so preset / sampling changes bust cache correctly. */
  clone_tune?: string
  /** Emotion preset (server merges into prosody; included for cache correctness). */
  emotion?: string
}): string {
  const payload = [
    params.text.trim(),
    params.voice_id,
    params.language,
    params.speed,
    params.pitch,
    params.volume,
    params.reverb,
    params.echo,
    params.noise_reduction ? '1' : '0',
    params.special_effect,
    params.clone_tune ?? '',
    params.emotion ?? 'neutral',
  ].join('\0')
  return hash(payload)
}

export function getCached(key: string): { buffer: ArrayBuffer; contentType: string } | null {
  const entry = cache.get(key)
  if (!entry) return null
  // Move to end (most recently used)
  const idx = keyOrder.indexOf(key)
  if (idx !== -1) {
    keyOrder.splice(idx, 1)
    keyOrder.push(key)
  }
  return { buffer: entry.buffer, contentType: entry.contentType }
}

export function setCached(key: string, buffer: ArrayBuffer, contentType: string): void {
  while (cache.size >= MAX_ENTRIES && keyOrder.length > 0) {
    const oldest = keyOrder.shift()!
    cache.delete(oldest)
  }
  cache.set(key, { buffer, contentType, createdAt: Date.now() })
  keyOrder.push(key)
}

import { Ratelimit } from "@upstash/ratelimit"
import { Redis } from "@upstash/redis"

// Check if Redis is configured
const hasRedis = process.env.UPSTASH_REDIS_REST_URL && process.env.UPSTASH_REDIS_REST_TOKEN

const redis = hasRedis ? new Redis({
  url: process.env.UPSTASH_REDIS_REST_URL!,
  token: process.env.UPSTASH_REDIS_REST_TOKEN!,
}) : null

// In-memory rate limiter for fallback (when Redis not configured)
// Uses Map to store request counts per identifier
const inMemoryStore = new Map<string, { count: number; resetTime: number }>()

// Cleanup old entries periodically
setInterval(() => {
  const now = Date.now()
  for (const [key, value] of inMemoryStore.entries()) {
    if (value.resetTime < now) {
      inMemoryStore.delete(key)
    }
  }
}, 60000) // Cleanup every minute

// Fallback rate limiter with in-memory storage
const createFallbackLimiter = (windowMs: number, maxRequests: number) => ({
  limit: async (identifier: string) => {
    const now = Date.now()
    const resetTime = now + windowMs

    // Get or create entry
    let entry = inMemoryStore.get(identifier)

    if (!entry || entry.resetTime < now) {
      // New window or expired entry
      entry = { count: 1, resetTime }
      inMemoryStore.set(identifier, entry)
      return {
        success: true,
        limit: maxRequests,
        remaining: maxRequests - 1,
        reset: resetTime,
      }
    }

    // Increment count
    entry.count++

    if (entry.count > maxRequests) {
      return {
        success: false,
        limit: maxRequests,
        remaining: 0,
        reset: entry.resetTime,
      }
    }

    inMemoryStore.set(identifier, entry)

    return {
      success: true,
      limit: maxRequests,
      remaining: maxRequests - entry.count,
      reset: entry.resetTime,
    }
  },
})

// Single-user mode: no effective rate limits (high ceilings so they never trigger)
const UNLIMITED_WINDOW_MS = 15 * 60 * 1000
const UNLIMITED_REQUESTS = 100000

// Create rate limiter: effectively unlimited for single user
export const rateLimiter = hasRedis && redis ? new Ratelimit({
  redis,
  limiter: Ratelimit.slidingWindow(UNLIMITED_REQUESTS, "15 m"),
  analytics: true,
  prefix: "@upstash/ratelimit",
}) : createFallbackLimiter(UNLIMITED_WINDOW_MS, UNLIMITED_REQUESTS)

// TTS: effectively unlimited for single user
export const ttsRateLimiter = hasRedis && redis ? new Ratelimit({
  redis,
  limiter: Ratelimit.slidingWindow(UNLIMITED_REQUESTS, "1 h"),
  analytics: true,
  prefix: "@upstash/ratelimit/tts",
}) : createFallbackLimiter(60 * 60 * 1000, UNLIMITED_REQUESTS)

// Cloning: effectively unlimited for single user
export const cloneRateLimiter = hasRedis && redis ? new Ratelimit({
  redis,
  limiter: Ratelimit.slidingWindow(UNLIMITED_REQUESTS, "1 d"),
  analytics: true,
  prefix: "@upstash/ratelimit/clone",
}) : createFallbackLimiter(24 * 60 * 60 * 1000, UNLIMITED_REQUESTS)
